'use client';

import { useRef, useState } from 'react';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { ArrowUpIcon, CodeIcon, FeatherIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ArtifactPanel } from './artifact-panel';
import { FILE_NAME, FIRST_REPLY, SECOND_REPLY } from './data';
import {
  APPLY_MS,
  canSendAt,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type ArtifactView,
  type Stage,
  type Version,
} from './session';
import { BottomSheet, DEFAULT_SPLIT, ResizeHandle } from './split';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function placeholderOf(stage: Stage) {
  if (stage === 0) {
    return 'Ask for a section of your page';
  }
  if (stage === 2) {
    return 'Ask for a change';
  }
  if (stage === 4) {
    return 'Replay to run the demonstration again';
  }
  return 'The assistant is writing';
}

function announcementOf(stage: Stage) {
  if (stage === 2) {
    return 'The first version is ready in the artifact.';
  }
  if (stage === 4) {
    return 'The second version is ready. Changes shows what moved.';
  }
  return '';
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

function isSendKey(event: React.KeyboardEvent<HTMLTextAreaElement>) {
  const isPlainEnter = event.key === 'Enter' && !event.shiftKey;
  return isPlainEnter && !event.nativeEvent.isComposing;
}

function AssistantTile() {
  return (
    <span
      aria-hidden='true'
      className='gem-plate inline-flex size-7 shrink-0 items-center justify-center rounded-lg [--gem:var(--primary)]'
    >
      <FeatherIcon className='size-4' />
    </span>
  );
}

function PersonMessage({ text }: { text: string }) {
  return (
    <p className='bg-foreground/[0.06] max-w-[85%] self-end rounded-2xl rounded-ee-md px-3.5 py-2 text-sm leading-relaxed'>
      {text}
    </p>
  );
}

function WorkingLine({ word }: { word: string }) {
  return (
    <p className='text-muted-foreground flex h-7 items-center gap-2 text-[13px]'>
      <span
        aria-hidden='true'
        className='bg-primary size-1.5 animate-pulse rounded-full'
      />
      {word}
    </p>
  );
}

type VersionCardProps = {
  version: Version;
  isCurrent: boolean;
  onOpen: (version: Version) => void;
};

function currentCardOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'ring-primary/50';
  }
  return 'ring-foreground/12';
}

function VersionCard({ version, isCurrent, onOpen }: VersionCardProps) {
  return (
    <button
      type='button'
      aria-pressed={isCurrent}
      onClick={() => onOpen(version)}
      className={cn(
        'bg-card hairline-ring hover:bg-foreground/[0.03] focus-visible:ring-ring dark:bg-foreground/[0.04] flex h-11 w-fit max-w-full cursor-pointer items-center gap-2.5 rounded-xl ps-2 pe-3 text-start shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-[background-color,box-shadow] duration-150 outline-none focus-visible:ring-2 active:scale-[0.97]',
        currentCardOf(isCurrent)
      )}
    >
      <span
        aria-hidden='true'
        className='keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md'
      >
        <CodeIcon className='size-3.5' />
      </span>
      <span className='flex min-w-0 flex-col leading-tight'>
        <span className='truncate font-mono text-xs font-medium'>
          {FILE_NAME}
        </span>
        <span className='text-muted-foreground text-xs'>Version {version}</span>
      </span>
    </button>
  );
}

type ReplyProps = {
  isWorking: boolean;
  workingWord: string;
  text: string;
  version: Version;
  currentVersion: Version;
  onOpen: (version: Version) => void;
};

function Reply({
  isWorking,
  workingWord,
  text,
  version,
  currentVersion,
  onOpen,
}: ReplyProps) {
  return (
    <div className='flex items-start gap-2.5'>
      <AssistantTile />
      {isWorking && <WorkingLine word={workingWord} />}
      {!isWorking && (
        <div className='flex min-w-0 flex-1 flex-col gap-2.5 pt-1'>
          <p className='text-sm leading-relaxed transition-opacity duration-300 starting:opacity-0'>
            {text}
          </p>
          <VersionCard
            version={version}
            isCurrent={version === currentVersion}
            onOpen={onOpen}
          />
        </div>
      )}
    </div>
  );
}

export default function AgentChat02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const [split, setSplit] = useState(DEFAULT_SPLIT);
  const layoutRef = useRef<HTMLDivElement>(null);
  const { schedule } = useTimeouts();
  const { stage } = state;
  const [firstAsk, secondAsk] = state.asks;
  const canSend = canSendAt(stage);
  const canReplay = isFinished && !isAutoplaying;
  const announcement = announcementOf(stage);
  const message = spokenUnless(isAutoplaying, announcement);
  const splitStyle = { '--split': `${split}%` } as React.CSSProperties;

  function changeSplit(next: number) {
    layoutRef.current?.style.setProperty('--split', `${next}%`);
    setSplit(next);
  }

  function send() {
    act({ type: 'sent' });
  }

  function handleKeys(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (!isSendKey(event)) {
      return;
    }
    event.preventDefault();
    send();
  }

  function openVersion(version: Version) {
    act({ type: 'version', version });
    act({ type: 'sheet', isOpen: true });
  }

  function apply() {
    act({ type: 'applying' });
    schedule(() => act({ type: 'applied' }), APPLY_MS);
  }

  function closeSheet() {
    act({ type: 'sheet', isOpen: false });
  }

  const panel = {
    stage,
    version: state.version,
    view: state.view,
    apply: state.apply,
    appliedVersion: state.appliedVersion,
    pressed,
    isActive: isInView,
    onVersionChange: (version: Version) => act({ type: 'version', version }),
    onViewChange: (view: ArtifactView) => act({ type: 'view', view }),
    onApply: apply,
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container relative h-dvh min-h-[36rem] w-full overflow-hidden'
      >
        <div
          ref={layoutRef}
          style={splitStyle}
          className='mx-auto flex h-full max-w-6xl p-3 @3xl:p-4'
        >
          <section
            aria-label='Conversation'
            className='flex w-full min-w-0 shrink-0 flex-col gap-3 @3xl:w-(--split)'
          >
            <header className='flex h-9 shrink-0 items-center gap-2.5'>
              <AssistantTile />
              <div className='flex min-w-0 flex-1 flex-col leading-tight'>
                <h2 className='truncate text-sm font-medium'>
                  Tallis landing page
                </h2>
                <span className='text-muted-foreground text-xs'>Assistant</span>
              </div>
              <ReplayButton isShown={canReplay} onReplay={restart} />
            </header>

            <div className='flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto py-2'>
              {stage === 0 && (
                <p className='text-muted-foreground m-auto max-w-xs text-center text-[13px]'>
                  Ask for a section. The code is written in the artifact, where
                  you can compare versions and apply one.
                </p>
              )}
              {firstAsk && <PersonMessage text={firstAsk} />}
              {stage >= 1 && (
                <Reply
                  isWorking={stage === 1}
                  workingWord={`Writing ${FILE_NAME}`}
                  text={FIRST_REPLY}
                  version={1}
                  currentVersion={state.version}
                  onOpen={openVersion}
                />
              )}
              {secondAsk && <PersonMessage text={secondAsk} />}
              {stage >= 3 && (
                <Reply
                  isWorking={stage === 3}
                  workingWord='Revising two places'
                  text={SECOND_REPLY}
                  version={2}
                  currentVersion={state.version}
                  onOpen={openVersion}
                />
              )}
            </div>

            <div className='bg-card hairline-ring ring-foreground/12 has-[textarea:focus-visible]:ring-ring/25 dark:bg-foreground/[0.04] dark:ring-foreground/15 flex items-end gap-2 rounded-2xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-[box-shadow] duration-150 has-[textarea:focus-visible]:ring-[3px]'>
              <textarea
                value={state.draft}
                rows={2}
                aria-label='Message to the assistant'
                placeholder={placeholderOf(stage)}
                onChange={(event) =>
                  act({ type: 'typed', text: event.target.value })
                }
                onKeyDown={handleKeys}
                className='placeholder:text-muted-foreground/75 min-h-12 flex-1 resize-none bg-transparent px-1.5 py-1 text-base leading-normal outline-none md:text-[13px]'
              />
              <Button
                type='button'
                size='icon'
                aria-label='Send the message'
                disabled={!canSend}
                onClick={send}
                className={pressedSolidOf(pressed === 'send')}
              >
                <ArrowUpIcon />
              </Button>
            </div>
          </section>

          <ResizeHandle
            split={split}
            containerRef={layoutRef}
            onSplitChange={changeSplit}
          />

          <aside
            aria-label='Artifact'
            className='bg-card hairline-ring ring-border hidden min-w-0 flex-1 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @3xl:flex'
          >
            <ArtifactPanel {...panel} className='w-full' />
          </aside>
        </div>

        <BottomSheet
          isOpen={state.isSheetOpen}
          label='Artifact'
          onClose={closeSheet}
        >
          <ArtifactPanel {...panel} className='flex-1' />
        </BottomSheet>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { CodeIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import {
  CHANGES,
  FILE_NAME,
  sourceOf,
  VERSIONS,
  type CodeLine,
  type DiffKind,
} from './data';
import type { ApplyStatus, ArtifactView, Stage, Version } from './session';

const LINE_MS = 150;

const VERSION_SEGMENTS: Segment<'v1' | 'v2'>[] = [
  { value: 'v1', label: 'v1' },
  { value: 'v2', label: 'v2' },
];

const VIEW_SEGMENTS: Segment<ArtifactView>[] = [
  { value: 'code', label: 'Code' },
  { value: 'changes', label: 'Changes' },
];

const APPLY_LABELS: Record<MorphState, string> = {
  idle: 'Apply',
  busy: 'Applying',
  done: 'Applied',
};

const FIRST_VERSION_KEYS = new Set(VERSIONS[1].map((line) => line.key));

const ADDED_COUNT = CHANGES.filter((line) => line.kind === 'added').length;

const REMOVED_COUNT = CHANGES.filter((line) => line.kind === 'removed').length;

function statusOf(stage: Stage, version: Version) {
  if (stage === 1) {
    return 'Writing';
  }
  if (stage === 3) {
    return 'Revising';
  }
  return `Version ${version}`;
}

function applyStateOf(
  apply: ApplyStatus,
  isAppliedVersion: boolean
): MorphState {
  if (apply === 'busy') {
    return 'busy';
  }
  if (isAppliedVersion) {
    return 'done';
  }
  return 'idle';
}

function versionOf(value: 'v1' | 'v2'): Version {
  if (value === 'v2') {
    return 2;
  }
  return 1;
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

function useRevealedCount(total: number, isStreaming: boolean) {
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (!isStreaming) {
      return;
    }
    const timer = setInterval(() => {
      setCount((current) => Math.min(total, current + 1));
    }, LINE_MS);
    return () => clearInterval(timer);
  }, [isStreaming, total]);

  return count;
}

function lineNumberOf(index: number) {
  return index + 1;
}

/** A line that the revision added lights for a moment when it lands; the lines around it do not move. */
function landingClassOf(isRevised: boolean) {
  if (isRevised) {
    return 'bg-primary/0 transition-colors duration-1000 ease-out starting:bg-primary/25';
  }
  return 'transition-opacity duration-300 starting:opacity-0';
}

function CodeRows({
  lines,
  marksRevision,
}: {
  lines: CodeLine[];
  marksRevision: boolean;
}) {
  return (
    <ol className='min-w-max py-2 font-mono text-xs leading-5'>
      {lines.map((line, index) => {
        const isNew = !FIRST_VERSION_KEYS.has(line.key);
        const isRevised = marksRevision && isNew;
        return (
          <li
            key={line.key}
            className={cn('flex gap-3 px-3', landingClassOf(isRevised))}
          >
            <span className='text-muted-foreground/60 w-5 shrink-0 text-end tabular-nums select-none'>
              {lineNumberOf(index)}
            </span>
            <code className='whitespace-pre'>{line.text}</code>
          </li>
        );
      })}
    </ol>
  );
}

/** Only this list re-renders while the first version is written. */
function StreamedCode({ isActive }: { isActive: boolean }) {
  const total = VERSIONS[1].length;
  const count = useRevealedCount(total, isActive);
  const lines = VERSIONS[1].slice(0, count);

  return <CodeRows lines={lines} marksRevision={false} />;
}

const DIFF_SIGN: Record<DiffKind, string> = {
  same: ' ',
  added: '+',
  removed: '-',
};

const DIFF_CLASS: Record<DiffKind, string> = {
  same: '',
  added: 'bg-success/10',
  removed: 'bg-destructive/10 text-muted-foreground line-through',
};

const DIFF_WORD: Record<DiffKind, string> = {
  same: '',
  added: 'Added: ',
  removed: 'Removed: ',
};

function ChangeRows() {
  return (
    <ol className='min-w-max py-2 font-mono text-xs leading-5'>
      {CHANGES.map((line) => (
        <li
          key={`${line.kind}-${line.key}`}
          className={cn('flex gap-3 px-3', DIFF_CLASS[line.kind])}
        >
          <span
            aria-hidden='true'
            className='text-muted-foreground w-5 shrink-0 text-center select-none'
          >
            {DIFF_SIGN[line.kind]}
          </span>
          <span className='sr-only'>{DIFF_WORD[line.kind]}</span>
          <code className='whitespace-pre'>{line.text}</code>
        </li>
      ))}
    </ol>
  );
}

export type ArtifactPanelProps = {
  stage: Stage;
  version: Version;
  view: ArtifactView;
  apply: ApplyStatus;
  appliedVersion: Version | null;
  pressed: string | null;
  isActive: boolean;
  onVersionChange: (version: Version) => void;
  onViewChange: (view: ArtifactView) => void;
  onApply: () => void;
  className?: string;
};

export function ArtifactPanel({
  stage,
  version,
  view,
  apply,
  appliedVersion,
  pressed,
  isActive,
  onVersionChange,
  onViewChange,
  onApply,
  className,
}: ArtifactPanelProps) {
  const isEmpty = stage === 0;
  const isWriting = stage === 1;
  const isReady = stage >= 2;
  const hasRevision = stage === 4;
  const showsChanges = hasRevision && view === 'changes';
  const showsCode = isReady && !showsChanges;
  const lines = VERSIONS[version];
  const status = statusOf(stage, version);
  const applyState = applyStateOf(apply, appliedVersion === version);

  return (
    <div className={cn('flex min-h-0 flex-col gap-3', className)}>
      <header className='flex items-center gap-2.5'>
        <span
          aria-hidden='true'
          className='keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md'
        >
          <CodeIcon className='size-3.5' />
        </span>
        <div className='flex min-w-0 flex-1 flex-col leading-tight'>
          <h3 className='truncate font-mono text-[13px] font-medium'>
            {FILE_NAME}
          </h3>
          {!isEmpty && (
            <Swap swapKey={status} className='text-muted-foreground text-xs'>
              {status}
            </Swap>
          )}
        </div>
        {isReady && <CopyButton text={sourceOf(lines)} label='Copy the code' />}
        {isReady && (
          <MorphButton
            type='button'
            size='sm'
            state={applyState}
            labels={APPLY_LABELS}
            onClick={onApply}
            className={pressedSolidOf(pressed === 'apply')}
          />
        )}
      </header>

      {hasRevision && (
        <div className='flex flex-wrap items-center gap-2'>
          <Segments
            label='Version'
            value={`v${version}`}
            segments={VERSION_SEGMENTS}
            onValueChange={(value) => onVersionChange(versionOf(value))}
          />
          <Segments
            label='View'
            value={view}
            segments={VIEW_SEGMENTS}
            onValueChange={onViewChange}
          />
          <span className='text-muted-foreground ms-auto text-xs tabular-nums'>
            <span className='text-success-foreground'>+{ADDED_COUNT}</span>{' '}
            <span className='text-destructive-ink'>-{REMOVED_COUNT}</span>
          </span>
        </div>
      )}

      <div className='bg-foreground/[0.04] min-h-0 flex-1 overflow-auto rounded-lg'>
        {isEmpty && (
          <p className='text-muted-foreground p-4 text-[13px]'>
            Nothing made yet. Ask for a section and its code is written here.
          </p>
        )}
        {isWriting && <StreamedCode isActive={isActive} />}
        {showsCode && <CodeRows lines={lines} marksRevision={hasRevision} />}
        {showsChanges && <ChangeRows />}
      </div>
    </div>
  );
}

'use client';

import { useRef } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

export const DEFAULT_SPLIT = 42;

const MIN_SPLIT = 30;

const MAX_SPLIT = 62;

const KEY_STEP = 2;

/** How far the sheet has to be dragged down before letting go closes it. */
const CLOSE_AFTER_PX = 80;

function bounded(percent: number) {
  const atLeast = Math.max(MIN_SPLIT, percent);
  return Math.min(MAX_SPLIT, atLeast);
}

function splitFromKey(key: string, split: number) {
  if (key === 'ArrowLeft') {
    return bounded(split - KEY_STEP);
  }
  if (key === 'ArrowRight') {
    return bounded(split + KEY_STEP);
  }
  if (key === 'Home') {
    return MIN_SPLIT;
  }
  if (key === 'End') {
    return MAX_SPLIT;
  }
  return null;
}

type ResizeHandleProps = {
  split: number;
  /** The element whose `--split` the handle drives. */
  containerRef: React.RefObject<HTMLElement | null>;
  onSplitChange: (split: number) => void;
};

/** While it is dragged the width is written to the container; React hears about it once, on release. */
export function ResizeHandle({
  split,
  containerRef,
  onSplitChange,
}: ResizeHandleProps) {
  const dragged = useRef<number | null>(null);

  function startDrag(event: React.PointerEvent<HTMLDivElement>) {
    event.currentTarget.setPointerCapture(event.pointerId);
    dragged.current = split;
  }

  function drag(event: React.PointerEvent<HTMLDivElement>) {
    const container = containerRef.current;
    const isDragging = dragged.current !== null;
    if (!container || !isDragging) {
      return;
    }
    const box = container.getBoundingClientRect();
    const offset = event.clientX - box.left;
    const percent = (offset / box.width) * 100;
    const next = bounded(percent);
    dragged.current = next;
    container.style.setProperty('--split', `${next}%`);
  }

  function endDrag() {
    const next = dragged.current;
    dragged.current = null;
    if (next !== null) {
      onSplitChange(Math.round(next));
    }
  }

  function moveWithKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    const next = splitFromKey(event.key, split);
    if (next === null) {
      return;
    }
    event.preventDefault();
    onSplitChange(next);
  }

  return (
    <div
      role='separator'
      tabIndex={0}
      aria-orientation='vertical'
      aria-label='Resize the conversation and the artifact'
      aria-valuemin={MIN_SPLIT}
      aria-valuemax={MAX_SPLIT}
      aria-valuenow={split}
      onPointerDown={startDrag}
      onPointerMove={drag}
      onPointerUp={endDrag}
      onPointerCancel={endDrag}
      onDoubleClick={() => onSplitChange(DEFAULT_SPLIT)}
      onKeyDown={moveWithKeys}
      className='group/handle focus-visible:ring-ring/25 hidden w-3 shrink-0 cursor-col-resize touch-none items-center justify-center rounded-full outline-none focus-visible:ring-[3px] @3xl:flex'
    >
      <span className='bg-foreground/15 group-hover/handle:bg-foreground/35 group-active/handle:bg-primary h-8 w-1 rounded-full transition-colors duration-150' />
    </div>
  );
}

function backdropOf(isOpen: boolean) {
  if (isOpen) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

function panelOf(isOpen: boolean) {
  if (isOpen) {
    return 'translate-y-0';
  }
  return 'translate-y-[calc(100%+1rem)]';
}

function layerOf(isOpen: boolean) {
  if (isOpen) {
    return undefined;
  }
  return 'pointer-events-none';
}

type BottomSheetProps = {
  isOpen: boolean;
  label: string;
  onClose: () => void;
  children: React.ReactNode;
};

/** Drawn inside the block. Its grip follows the finger and closes the sheet when it is pulled far enough. */
export function BottomSheet({
  isOpen,
  label,
  onClose,
  children,
}: BottomSheetProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const startY = useRef<number | null>(null);
  const pulled = useRef(0);

  function startPull(event: React.PointerEvent<HTMLButtonElement>) {
    event.currentTarget.setPointerCapture(event.pointerId);
    startY.current = event.clientY;
    pulled.current = 0;
  }

  function pull(event: React.PointerEvent<HTMLButtonElement>) {
    const panel = panelRef.current;
    const origin = startY.current;
    if (!panel || origin === null) {
      return;
    }
    const distance = Math.max(0, event.clientY - origin);
    pulled.current = distance;
    panel.style.transition = 'none';
    panel.style.translate = `0 ${distance}px`;
  }

  function endPull() {
    const panel = panelRef.current;
    const wasPulling = startY.current !== null;
    startY.current = null;
    if (!panel || !wasPulling) {
      return;
    }
    panel.style.transition = '';
    panel.style.translate = '';
    if (pulled.current > CLOSE_AFTER_PX) {
      pulled.current = 0;
      onClose();
    }
  }

  function closeFromGrip() {
    const wasPulled = pulled.current > 4;
    pulled.current = 0;
    if (!wasPulled) {
      onClose();
    }
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      onClose();
    }
  }

  return (
    <div
      inert={!isOpen}
      onKeyDown={closeOnEscape}
      className={cn('absolute inset-0 z-10 @3xl:hidden', layerOf(isOpen))}
    >
      <div
        aria-hidden='true'
        onClick={onClose}
        className={cn(
          'absolute inset-0 bg-black/40 transition-opacity duration-200',
          backdropOf(isOpen)
        )}
      />
      <div
        ref={panelRef}
        role='dialog'
        aria-label={label}
        className={cn(
          'bg-card hairline-ring ring-border absolute inset-x-2 bottom-2 flex h-[78%] flex-col rounded-2xl px-4 pb-4 shadow-xl shadow-black/8 transition-[translate] duration-300 ease-(--ease-drawer)',
          panelOf(isOpen)
        )}
      >
        <button
          type='button'
          aria-label='Close the artifact'
          onClick={closeFromGrip}
          onPointerDown={startPull}
          onPointerMove={pull}
          onPointerUp={endPull}
          onPointerCancel={endPull}
          className='group/grip flex h-7 w-full shrink-0 cursor-grab touch-none items-center justify-center outline-none active:cursor-grabbing'
        >
          <span className='bg-foreground/20 group-focus-visible/grip:bg-primary h-1 w-9 rounded-full' />
        </button>
        {children}
      </div>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { FIRST_PROMPT, SECOND_PROMPT } from './data';

/** 0 nothing asked, 1 writing the first version, 2 first version ready, 3 revising, 4 second version ready. */
export type Stage = 0 | 1 | 2 | 3 | 4;

export type Version = 1 | 2;

export type ArtifactView = 'code' | 'changes';

export type ApplyStatus = 'idle' | 'busy' | 'done';

export type ArtifactState = {
  draft: string;
  asks: string[];
  stage: Stage;
  version: Version;
  view: ArtifactView;
  apply: ApplyStatus;
  appliedVersion: Version | null;
  isSheetOpen: boolean;
};

export type ArtifactAction =
  | { type: 'typed'; text: string }
  | { type: 'sent' }
  | { type: 'wrote' }
  | { type: 'version'; version: Version }
  | { type: 'view'; view: ArtifactView }
  | { type: 'applying' }
  | { type: 'applied' }
  | { type: 'sheet'; isOpen: boolean };

type Step = SessionStep<ArtifactState, ArtifactAction>;

export const INITIAL: ArtifactState = {
  draft: '',
  asks: [],
  stage: 0,
  version: 1,
  view: 'code',
  apply: 'idle',
  appliedVersion: null,
  isSheetOpen: false,
};

export function canSendAt(stage: Stage) {
  return stage === 0 || stage === 2;
}

function fallbackPromptOf(stage: Stage) {
  if (stage === 0) {
    return FIRST_PROMPT;
  }
  return SECOND_PROMPT;
}

function askOf(state: ArtifactState) {
  const trimmed = state.draft.trim();
  if (trimmed === '') {
    return fallbackPromptOf(state.stage);
  }
  return trimmed;
}

function sent(state: ArtifactState): ArtifactState {
  if (!canSendAt(state.stage)) {
    return state;
  }
  const asks = [...state.asks, askOf(state)];
  if (state.stage === 0) {
    return { ...state, draft: '', asks, stage: 1 };
  }
  return { ...state, draft: '', asks, stage: 3 };
}

function wrote(state: ArtifactState): ArtifactState {
  if (state.stage === 1) {
    return { ...state, stage: 2, version: 1 };
  }
  if (state.stage === 3) {
    return { ...state, stage: 4, version: 2, apply: 'idle' };
  }
  return state;
}

function applied(state: ArtifactState): ArtifactState {
  if (state.apply !== 'busy') {
    return state;
  }
  return { ...state, apply: 'done', appliedVersion: state.version };
}

export function reducer(
  state: ArtifactState,
  action: ArtifactAction
): ArtifactState {
  switch (action.type) {
    case 'typed':
      return { ...state, draft: action.text };
    case 'sent':
      return sent(state);
    case 'wrote':
      return wrote(state);
    case 'version':
      return { ...state, version: action.version, apply: 'idle' };
    case 'view':
      return { ...state, view: action.view };
    case 'applying':
      return { ...state, apply: 'busy' };
    case 'applied':
      return applied(state);
    case 'sheet':
      return { ...state, isSheetOpen: action.isOpen };
  }
}

const CHUNK = 3;

function delayOfChunk(index: number, startAfter: number) {
  if (index === 0) {
    return startAfter;
  }
  return 70;
}

function typingSteps(text: string, startAfter: number): Step[] {
  const steps: Step[] = [];
  const last = text.length + CHUNK;
  for (let end = CHUNK; end < last; end += CHUNK) {
    const typed = text.slice(0, end);
    const after = delayOfChunk(steps.length, startAfter);
    steps.push({ after, by: 'demo', action: { type: 'typed', text: typed } });
  }
  return steps;
}

function hasAskedOnce(state: ArtifactState) {
  return state.stage >= 1;
}

function hasAskedTwice(state: ArtifactState) {
  return state.stage >= 3;
}

/** How long a version takes to write: the panel streams its lines during that time. */
export const WRITE_MS = 2600;

export const REVISE_MS = 1700;

export const APPLY_MS = 900;

export const SCRIPT: Step[] = [
  ...typingSteps(FIRST_PROMPT, 1000),
  {
    after: 450,
    by: 'person',
    press: 'send',
    action: { type: 'sent' },
    isAnswered: hasAskedOnce,
  },
  { after: 500, by: 'demo', action: { type: 'sheet', isOpen: true } },
  { after: WRITE_MS, action: { type: 'wrote' } },
  { after: 1500, by: 'demo', action: { type: 'sheet', isOpen: false } },
  ...typingSteps(SECOND_PROMPT, 500),
  {
    after: 450,
    by: 'person',
    press: 'send',
    action: { type: 'sent' },
    isAnswered: hasAskedTwice,
  },
  { after: 500, by: 'demo', action: { type: 'sheet', isOpen: true } },
  { after: REVISE_MS, action: { type: 'wrote' } },
  { after: 1700, by: 'demo', action: { type: 'view', view: 'changes' } },
  { after: 1900, by: 'demo', press: 'apply', action: { type: 'applying' } },
  { after: APPLY_MS, action: { type: 'applied' } },
  { after: 1600, by: 'demo', action: { type: 'sheet', isOpen: false } },
];

function restingOf() {
  let state = INITIAL;
  for (const step of SCRIPT) {
    state = reducer(state, step.action);
  }
  return state;
}

export const RESTING = restingOf();

export const LOOP_AFTER_MS = 2600;

